import CartType from './CartType';
class Cart {
    _gameObjects;
    _name = 'title';
    _description = 'description';
    _effects;
    _type;
    _action;
    constructor(gameObject, name = 'title', description = 'description', type = CartType.Item, action = () => { }) {
        this._action = action;
        this._gameObjects = gameObject;
        this._name = name;
        this._description = description;
        this._type = type;
    }
    title() {
        return this._name;
    }
    description() {
        return this._description;
    }
    effects() {
    }
    setAction(action) {
        this._action = action;
    }
    action() {
        this._action();
        //this._gameObjects.getStep().addStep();
    }
    type() {
        return this._type;
    }
}
export default Cart;
